/**
 * rule-engine.ts —— 自动化规则引擎（B20，纯函数版）
 *
 * 核心模型：IFTTT（If This Then That）
 *   - 触发器（trigger）：规则何时被激活
 *   - 条件（condition）：激活后还要满足什么才执行（可选）
 *   - 动作（actions）：执行什么操作（可多个，按顺序）
 *
 * 本文件只包含纯函数（匹配判断 + 动作计算），不做副作用。
 * 副作用（修改任务、发通知、加评论等）由 service 层在动作结果指导下完成。
 */
export type TriggerType = 'task_overdue' | 'task_due_soon' | 'status_changed' | 'label_added' | 'label_removed' | 'priority_changed';
export interface TriggerConfig {
    days?: number;
    fromStatus?: string;
    toStatus?: string;
    label?: string;
    fromPriority?: string;
    toPriority?: string;
}
export interface RuleCondition {
    assigneeIds?: string[];
    excludeAssigneeIds?: string[];
    labels?: string[];
    anyLabels?: string[];
    noLabels?: string[];
    priorityGte?: string;
    priorityLte?: string;
    statusIn?: string[];
    statusNotIn?: string[];
}
export type ActionType = 'set_priority' | 'set_status' | 'set_assignee' | 'add_label' | 'remove_label' | 'add_comment' | 'send_notification';
export interface RuleAction {
    type: ActionType;
    config: any;
}
export interface RuleLike {
    id: string;
    triggerType: string;
    triggerConfig: any;
    conditionConfig: any;
    actions: any;
    isEnabled: boolean;
}
export interface TaskLike {
    id: string;
    title: string;
    status: string;
    priority: string;
    assigneeId?: string | null;
    dueAt?: Date | string | null;
    tags: string[];
    [key: string]: any;
}
export interface EvalContext {
    eventType?: 'status_changed' | 'label_changed' | 'priority_changed' | 'scan_overdue' | 'scan_due_soon';
    changedFields?: {
        status?: {
            old: string;
            new: string;
        };
        priority?: {
            old: string;
            new: string;
        };
        labelsAdded?: string[];
        labelsRemoved?: string[];
    };
    now?: Date;
}
export interface ActionResult {
    action: ActionType;
    success: boolean;
    target?: string;
    value?: any;
    detail?: string;
}
/**
 * 判断一条规则在当前上下文下是否触发。
 * 注意：只判断触发器本身 + 条件，不执行动作。
 */
export declare function matchRule(rule: RuleLike, task: TaskLike, ctx?: EvalContext): boolean;
/**
 * 计算动作效果（纯函数，不修改任务）。
 * service 层根据返回的 ActionResult 列表执行实际副作用。
 */
export declare function evaluateActions(actions: RuleAction[], task: TaskLike): ActionResult[];
export declare function findMatchingRules(rules: RuleLike[], task: TaskLike, ctx?: EvalContext): RuleLike[];
export declare const SYSTEM_TEMPLATES: Omit<RuleLike, 'id'>[];
